package com.seengeem.assistant;
import android.content.pm.*;import android.os.Build;import org.json.*;import javax.net.ssl.HttpsURLConnection;import java.io.*;import java.net.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;import java.util.concurrent.*;
final class UpdateManager {
 static final String PREFIX="https://github.com/mostafa0mahmoud9-source/seengeem-assistant-app/releases/download/";
 static final String FEED="https://api.github.com/repos/mostafa0mahmoud9-source/seengeem-assistant-app/releases/latest";
 final MainActivity activity;final ExecutorService executor=Executors.newSingleThreadExecutor();volatile boolean checking=false,ready=false;long checked=0;
 UpdateManager(MainActivity a){activity=a;}
 boolean ready(){return ready;}
 void check(boolean manual){if(checking||(!manual&&System.currentTimeMillis()-checked<1800000))return;checking=true;checked=System.currentTimeMillis();executor.execute(()->{try{JSONObject release=new JSONObject(new String(downloadBytes(FEED,1000000),StandardCharsets.UTF_8));if(release.optBoolean("draft")||release.optBoolean("prerelease"))return;String feed=null;JSONArray assets=release.getJSONArray("assets");for(int i=0;i<assets.length();i++){JSONObject a=assets.getJSONObject(i);if(a.getString("name").equals("android-update.json"))feed=a.getString("browser_download_url");}if(feed==null||!feed.startsWith(PREFIX))return;JSONObject manifest=new JSONObject(new String(downloadBytes(feed,65536),StandardCharsets.UTF_8));long version=manifest.getLong("versionCode");if(version<=BuildConfig.VERSION_CODE){if(manual)activity.notice("البرنامج على أحدث إصدار متاح");return;}String url=manifest.getString("url"),hash=manifest.getString("sha256");if(!url.startsWith(PREFIX)||!url.endsWith(".apk")||!hash.matches("[a-fA-F0-9]{64}"))throw new IOException("Invalid update metadata");
  File part=new File(activity.getCacheDir(),"update.part");try(InputStream input=open(url);OutputStream output=new FileOutputStream(part)){byte[] buffer=new byte[32768];int count;long size=0;while((count=input.read(buffer))!=-1){size+=count;if(size>150000000)throw new IOException("Too large");output.write(buffer,0,count);}}
  if(!digest(part).equalsIgnoreCase(hash)){part.delete();throw new IOException("Checksum mismatch");}
  PackageManager pm=activity.getPackageManager();int flag=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo apk=pm.getPackageArchiveInfo(part.getAbsolutePath(),flag);PackageInfo own=pm.getPackageInfo(activity.getPackageName(),flag);if(apk==null||!activity.getPackageName().equals(apk.packageName)||(Build.VERSION.SDK_INT>=28?apk.getLongVersionCode():apk.versionCode)!=version||!signatures(apk).equals(signatures(own))){part.delete();throw new IOException("Untrusted signing identity");}
  File target=new File(activity.getCacheDir(),"update.apk");if(target.exists()&&!target.delete())throw new IOException("Cannot replace update");if(!part.renameTo(target))throw new IOException("Cannot store update");ready=true;activity.notice("تحديث جاهز — اضغط تثبيت التحديث عندما يناسبك");
 }catch(Exception e){if(manual)activity.notice("تعذر فحص التحديث الآن؛ النسخة الحالية محفوظة");}finally{checking=false;}});}
 static Set<String> signatures(PackageInfo info)throws Exception{android.content.pm.Signature[] list=Build.VERSION.SDK_INT>=28?info.signingInfo.getApkContentsSigners():info.signatures;Set<String> out=new HashSet<>();for(android.content.pm.Signature s:list)out.add(hex(MessageDigest.getInstance("SHA-256").digest(s.toByteArray())));return out;}
 static String hex(byte[] bytes){StringBuilder result=new StringBuilder();for(byte b:bytes)result.append(String.format(Locale.ROOT,"%02x",b&255));return result.toString();}
 static String digest(File f)throws Exception{MessageDigest d=MessageDigest.getInstance("SHA-256");try(InputStream input=new FileInputStream(f)){byte[] b=new byte[32768];int n;while((n=input.read(b))!=-1)d.update(b,0,n);}return hex(d.digest());}
 static InputStream open(String address)throws Exception{URL url=new URL(address);for(int i=0;i<6;i++){if(!url.getProtocol().equals("https"))throw new IOException("HTTPS required");String host=url.getHost();if(!host.equals("api.github.com")&&!host.equals("github.com")&&!host.endsWith(".githubusercontent.com"))throw new IOException("Invalid host");HttpsURLConnection c=(HttpsURLConnection)url.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(30000);c.setRequestProperty("User-Agent","SeenGeem-Assistant/"+BuildConfig.VERSION_NAME);c.setInstanceFollowRedirects(false);int code=c.getResponseCode();if(code>=300&&code<400){url=new URL(url,c.getHeaderField("Location"));c.disconnect();continue;}if(code!=200){c.disconnect();throw new IOException("HTTP "+code);}return c.getInputStream();}throw new IOException("Redirect limit");}
 static byte[] downloadBytes(String url,int maximum)throws Exception{try(InputStream i=open(url);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=i.read(b))!=-1){if(out.size()+n>maximum)throw new IOException("Too large");out.write(b,0,n);}return out.toByteArray();}}
 void close(){executor.shutdownNow();}
}
